const smsHtml=sms?`<div class="ai-sms"><b>${sms.counts.submitted+sms.counts.recorded} of ${sms.results.length} ${sms.channel==='inbox'?'recorded in the test inbox (no SMS sent)':`submitted to ${chan().via}`}</b><span class="ai-engine">${esc(sms.recipient)}</span>${sms.results.map(r=>`<div class="ai-sms-row"><span>${esc(languageMeta(r.code).native)}</span><span>${esc(r.status)}</span></div>`).join('')}</div>`:'';
