function aiBusyEnd(){state.aiBusy='';render()}
async function aiPlan(){const sel=selectedFeatures(),f=focusFeature(sel);if(!f||state.aiBusy)return;const p=f.properties;state.aiBusy='plan';render();try{let plan;if(state.connected)plan=await api('/api/console/language-plan',{method:'POST',body:JSON.stringify({geoid:p.GEOID})});else plan={geoid:p.GEOID,name:p.name,source:'rules',engine:'Share-based rule (local)',languages:recommendedLanguages([p]),added_by_floor:[],rationale:'Local mode ranks supported languages by population-weighted share. Connect the backend to use Gemini.'};state.aiPlans[p.GEOID]=plan;delete state.aiTexts[p.GEOID];delete state.aiSms[p.GEOID];log(`Language plan for ${p.name}: ${plan.languages.join(', ')} (${plan.engine}).`)}catch(e){toast('Language plan failed: '+e.message)}aiBusyEnd()}
async function aiTranslate(){const sel=selectedFeatures(),f=focusFeature(sel);if(!f||state.aiBusy)return;const p=f.properties,plan=state.aiPlans[p.GEOID];if(!plan)return;state.aiBusy='tx';render();try{let tx;if(state.connected)tx=await api('/api/console/translate',{method:'POST',body:JSON.stringify({geoid:p.GEOID,languages:plan.languages})});else tx={geoid:p.GEOID,name:p.name,languages:plan.languages,engine:'Fixed templates (local)',requires_language_review:plan.languages.some(c=>!languageMeta(c).reviewed),messages:Object.fromEntries(plan.languages.map(c=>[c,{text:renderAlert(c,{area:p.name}),reviewed:languageMeta(c).reviewed,rtl:!!languageMeta(c).rtl,source:'template'}]))};state.aiTexts[p.GEOID]=tx;delete state.aiSms[p.GEOID];log(`Translated exercise message for ${p.name} into ${tx.languages.length} language(s) (${tx.engine}).`)}catch(e){toast('Translation failed: '+e.message)}aiBusyEnd()}
