async function aiSendSms(){const sel=selectedFeatures(),f=focusFeature(sel);if(!f||state.aiBusy)return;const p=f.properties,tx=state.aiTexts[p.GEOID];if(!tx)return;if(!state.connected){toast('Connect the backend to send an SMS.');return}const reviewer=((($('#console-reviewer')||{}).value)||'').trim();if(!reviewer||!($('#console-check')||{}).checked){toast('Enter your name and confirm you reviewed the messages.');return}state.aiBusy='sms';state.lastReviewer=reviewer;render();try{const res=await api('/api/console/send-sms',{method:'POST',body:JSON.stringify({request_id:crypto.randomUUID().replace(/-/g,''),geoid:p.GEOID,reviewer,reviewed:true,texts:Object.fromEntries(tx.languages.map(c=>[c,tx.messages[c].text]))})});state.aiSms[p.GEOID]=res;log(`Exercise SMS for ${p.name}: ${res.counts.submitted+res.counts.recorded} of ${res.results.length} ${res.channel==='inbox'?'recorded in the test inbox':`submitted via ${chan().via}`}. No public alert issued.`);toast(res.channel==='inbox'?'Recorded in the test inbox. No SMS was sent.':`Exercise ${chan().noun} submitted to ${chan().via}.`)}catch(e){toast('SMS not sent: '+e.message)}aiBusyEnd()}
function consoleView(){if(!state.districts.length)return `<section class="panel empty"><h2>Loading recipients…</h2></section>`;const sel=selectedFeatures();const plan=buildLanguagePlan(sel,state.languageMode);const active=plan.languages.includes(state.activeLang)?state.activeLang:(plan.languages[0]||'en');const example=plan.areas.find(a=>a.messages.some(m=>m.code===active));const message=example?.messages.find(m=>m.code===active);return `<div class="console"><aside class="rail panel"><div class="panel-head"><h2>Recipients</h2><span class="badge">${state.districts.length}</span></div><div class="rail-actions">${btn('Select all','select-all-areas','small')}${btn('Clear','clear-areas','small')}</div><div class="rail-scroll">${['municipality','district'].map(kind=>`<div class="rail-group">${kind==='municipality'?'MUNICIPALITIES':'DISTRICTS'}</div>${state.districts.filter(f=>f.properties.kind===kind).map(areaRow).join('')}`).join('')}</div></aside><section class="compose panel"><div class="panel-head"><h2>Multilingual exercise bundle</h2><span class="badge">${plan.areas.length} areas · ${plan.message_count} messages</span></div><div class="compose-body"><div class="bundle-strategy"><button data-language-mode="auto" aria-pressed="${state.languageMode==='auto'}"><b>Automatic per district</b><span>English + supported languages in each area's data</span></button><button data-language-mode="all" aria-pressed="${state.languageMode==='all'}"><b>All 9 supported languages</b><span>Every supported template for every selected area</span></button></div><p class="bundle-summary">${plan.areas.length?`One review. One batch. <b>${plan.languages.length} languages</b> across <b>${plan.areas.length} areas</b>.`:'Select recipients to prepare all relevant language versions automatically.'}</p>${plan.has_illustrative_data?'<p class="rev-note">Language recommendations use illustrative demographic data. They are not verified population coverage.</p>':''}${plan.has_coverage_gaps?'<p class="rev-note">Some language categories are grouped or unsupported. This bundle does not cover every language spoken.</p>':''}${aiPanel(sel)}<details class="bundle-details"><summary>Fixed fallback templates (used only if Gemini is unavailable) · ${plan.message_count} messages</summary>${plan.areas.map(a=>`<div class="bundle-area"><strong>${esc(a.name)}</strong><span>${a.messages.map(m=>esc(languageMeta(m.code).label)).join(' · ')}</span>${a.gaps.length?`<small>Coverage gaps / grouped categories: ${a.gaps.map(esc).join(', ')}</small>`:''}${a.messages.map(m=>`<details><summary>${esc(languageMeta(m.code).native)}${m.reviewed?'':' · native-speaker review pending'}</summary><p dir="${m.rtl?'rtl':'ltr'}">${esc(m.text)}</p></details>`).join('')}</div>`).join('')}</details><div class="lang-bar"><span class="lang-label">Fixed template preview · Gemini's own drafts appear in the AI panel above</span><div class="lang-pills">${plan.languages.map(code=>`<button class="lang-pill ${code===active?'on':''}" data-lang="${code}">${esc(languageMeta(code).native)}</button>`).join('')}</div></div>${message?`<div class="preview-area">${esc(example.name)}</div><div class="alert-preview" dir="${message.rtl?'rtl':'ltr'}">${esc(message.text)}</div>`:''}${plan.requires_language_review?'<p class="rev-note">Non-English templates remain pending native-speaker review. Exercise recording only.</p>':''}<div class="compose-foot"><label class="form-row">Reviewer name<input id="console-reviewer" placeholder="Your name" autocomplete="name" maxlength="80" value="${esc(state.lastReviewer||'')}"></label><label class="check"><input type="checkbox" id="console-check">I reviewed the recipients, language bundle and coverage gaps. Record this as an exercise only.</label>${btn(`Record complete bundle${plan.message_count?' · '+plan.message_count+' messages':''}`,'broadcast','primary','bell')}<p class="disclaimer">${state.connected?'Stores every localized message on the backend.':'Local mode: stores this exercise in your browser only.'} No real SMS or public alert is sent.</p></div></div></section><section class="thread panel"><div class="panel-head"><h2>Bundle log</h2><span class="badge">${state.threads.length}</span></div><div class="thread-scroll">${state.threads.length?state.threads.map(t=>`<div class="thread-item"><div class="thread-top"><time>${new Date(t.time).toLocaleString()}</time><span class="badge">${esc(t.status)}</span></div><div class="thread-areas">${t.areas.map(esc).join(', ')}</div><div class="thread-langs">${t.languages.map(c=>esc(languageMeta(c).native)).join(' · ')}</div><div class="thread-by">${t.message_count||'—'} messages · ${esc(t.reviewer)}</div></div>`).join(''):'<div class="empty">Select areas and record one complete multilingual bundle.</div>'}</div></section></div>`}

// ===== Live Explorer: mock fire runs with live rerouting =====
const STEPS_PER_SEC=0.4;          // one 5-minute fire step every 2.5 s at 1x
const TRIP_STEPS=14;              // the demo vehicle covers its first route in about 14 steps
const COMPASS=['N','NE','E','SE','S','SW','W','NW'];
const compass=deg=>COMPASS[Math.round((((Number(deg)||0)%360)+360)%360/45)%8];
const sim={runId:'altadena',data:null,origin:null,destName:'',step:0,playing:false,speed:1,raf:0,lastTs:0,uiAt:0,followAt:0,
  frameIndex:-1,hazard:null,planHazard:null,area:0,lastArea:0,vehicleM:0,vstep:null,route:null,routeCoords:null,plan:null,lastPlanAt:0,planning:false,planToken:0,
  calls:0,reroutes:0,arrived:false,stale:false,showAlts:true,follow:false,events:[],
  status:{kind:'idle',headline:'Pick a fire run',detail:'Choose a run on the left, then press Play.'}};
const districtCentroid=geoid=>{const f=state.districts.find(x=>x.properties.GEOID===geoid);return f?f.properties.centroid:null};
const districtName=geoid=>{const f=state.districts.find(x=>x.properties.GEOID===geoid);return f?f.properties.name:''};
const clockText=()=>{const m=Math.round(Math.min(sim.step,RUN_STEPS)*STEP_MINUTES);return `T+${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`};
const km=m=>(m/1000).toFixed(1);
function addEvent(text){sim.events.unshift({t:clockText(),text});sim.events=sim.events.slice(0,5)}
function cellCentroids(fire){return {type:'FeatureCollection',features:fire.features.map(f=>{const r=f.geometry.coordinates[0];return {type:'Feature',properties:{heat:f.properties.heat},geometry:{type:'Point',coordinates:[(r[0][0]+r[2][0])/2,(r[0][1]+r[2][1])/2]}}})}}
function assemblyFeatures(){return ASSEMBLY_POINTS.map(a=>({type:'Feature',properties:{name:a.name,state:pointInHazard(a.lonlat,sim.hazard)?'lost':(a.name===sim.destName?'target':'idle')},geometry:{type:'Point',coordinates:a.lonlat}}))}
const currentFrame=()=>sim.data.frames[Math.max(0,Math.min(sim.frameIndex,sim.data.frames.length-1))];

function showFrame(i){
  if(!sim.data)return;
  sim.frameIndex=Math.max(0,Math.min(i,sim.data.frames.length-1));
  const f=sim.data.frames[sim.frameIndex];
  const ahead=sim.data.frames[Math.min(sim.frameIndex+LOOKAHEAD_STEPS,sim.data.frames.length-1)];
  sim.hazard=f.hazardCells;sim.planHazard=ahead.hazardCells;sim.lastArea=sim.area;sim.area=hazardAreaKm2(f.hazardCells);sim.planArea=hazardAreaKm2(ahead.hazardCells);
  setSim({fire:f.fire,firePts:cellCentroids(f.fire),assembly:assemblyFeatures(),projected:{type:'Feature',properties:{},geometry:ahead.hazardCells}});
}

// ---- routing: our backend when connected, otherwise OSRM straight from the browser ----
async function osrmDirect(origin,dest,hazard,signal){
  const url=`https://router.project-osrm.org/route/v1/driving/${origin[0]},${origin[1]};${dest[0]},${dest[1]}?alternatives=true&overview=full&geometries=geojson`;
  const r=await fetch(url,{signal});
  if(!r.ok)throw new Error('Routing service returned '+r.status);
  const j=await r.json();
  if(j.code!=='Ok'||!(j.routes||[]).length)throw new Error('No road route found');
  const listed=j.routes.map((x,i)=>({id:'R'+(i+1),distance_m:Math.round(x.distance),duration_s:Math.round(x.duration),geometry:x.geometry,safe:!lineHitsHazard(x.geometry.coordinates,hazard)}));
  const safe=listed.filter(x=>x.safe);
  if(!safe.length)return {withheld:true,route:null,reason:'Every candidate route crosses the fire.',candidate_routes:listed};
  const best=safe.reduce((a,b)=>a.distance_m<=b.distance_m?a:b);
  return {withheld:false,route:{type:'Feature',geometry:best.geometry,properties:{distance_m:best.distance_m,duration_s:best.duration_s}},candidate_routes:listed,chosen_id:best.id};
}
async function fetchRoute(origin,dest,hazard){
  sim.calls++;
  const signal=AbortSignal.timeout(15000);
  if(state.connected){
    try{
      const r=await fetch(`${state.api}/api/evac-route`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({origin,dest,avoid:hazard}),signal});
      if(r.ok)return await r.json();
    }catch(e){}
  }
  return osrmDirect(origin,dest,hazard,signal);
}
async function planRoute(reason){
  if(!sim.data||sim.planning)return;
  sim.planning=true;sim.lastPlanAt=performance.now();
  const token=++sim.planToken;
  const origin=sim.vehicle?sim.vehicle:sim.origin;
  const hazard=sim.planHazard;
  let found=null,lastTry=null,error=null;
  try{
    const out=await chooseRoute({origin,hazard,primary:runById(sim.runId).primary,points:ASSEMBLY_POINTS,fetchRoute,isStale:()=>token!==sim.planToken});
    if(out.stale)return;
    found=out.found;lastTry=out.lastTry;
  }catch(e){error=e}
  if(token!==sim.planToken)return;
  sim.planning=false;
  if(error&&!found){sim.stale=true;if(!sim.plan)setStatus('idle','Routing unavailable','The routing service did not answer. The fire keeps running; the last route stays on screen.');renderLive();return}
  sim.stale=false;
  applyPlan(found,lastTry,reason);
}

function applyPlan(found,lastTry,reason){
  // "Fire nearby" checks only refresh the risk colouring. The route changes when the current one is blocked.
  if(found&&keepCurrentRoute({reason,routeCoords:sim.routeCoords,vehicleM:sim.vehicleM,hazard:sim.planHazard})){
    setSim({routeStops:riskStops(sim.routeCoords,sim.planHazard)});
    renderLive();return;
  }
  const prev=sim.plan;
  const {next,diff,switched}=describePlan({plan:sim.plan,route:sim.route,routeCoords:sim.routeCoords,vehicleM:sim.vehicleM,destName:sim.destName,found});
  const shown=found||lastTry;
  const cands=((shown&&shown.res.candidate_routes)||[]);
  const chosen=found?found.res.chosen_id:null;
  const blocked=[],alts=[],eta=[];
  for(const c of cands){
    const line=c.geometry.coordinates;
    if(c.id!==chosen){
      const sp=splitByHazard(line,sim.planHazard);
      for(const seg of sp.blocked)blocked.push({type:'Feature',properties:{},geometry:{type:'LineString',coordinates:seg}});
      for(const seg of sp.safe)alts.push({type:'Feature',properties:{},geometry:{type:'LineString',coordinates:seg}});
    }
    const mid=pointAlong(line,lineLength(line)/2).point;
    if(mid)eta.push({type:'Feature',properties:{label:`${Math.max(1,Math.round(c.duration_s/60))} min`,chosen:c.id===chosen},geometry:{type:'Point',coordinates:mid}});
  }
  const dName=found?found.dest.name:(lastTry?lastTry.dest.name:sim.destName);
  const oldRoute=sim.route;
  if(found){
    sim.route=found.res.route;sim.routeCoords=found.res.route.geometry.coordinates;sim.vehicleM=0;sim.arrived=false;
    if(!sim.vstep)sim.vstep=Math.min(900,Math.max(250,lineLength(sim.routeCoords)/TRIP_STEPS));
    sim.destName=found.dest.name;
    const dMin=Math.round(found.res.route.properties.duration_s/60),dKm=km(found.res.route.properties.distance_m);
    if(diff.kind==='new'){setStatus('clear','Route ready',`To ${dName}: ${dKm} km, about ${dMin} min.`)}
    else if(diff.kind==='rerouted'||switched){
      sim.reroutes++;
      const why=reason==='blocked'?'The fire is projected to cut the road ahead within 15 minutes.':'The fire is closing in on the route.';
      setStatus('rerouted','Rerouted',`${why} ${switched?`New assembly point: ${dName}. `:''}${diff.dMin>=0?'+':''}${diff.dMin} min, ${diff.dKm>=0?'+':''}${diff.dKm} km.`);
      addEvent(`Rerouted${switched?` to ${dName}`:''} (${diff.dMin>=0?'+':''}${diff.dMin} min)`);
    }else if(diff.kind==='resumed'){setStatus('clear','Route restored',`A safe route to ${dName} is open again.`);addEvent('Route restored')}
    else if(sim.status.kind!=='rerouted'&&sim.status.kind!=='clear')setStatus('clear','Route clear',`To ${dName}: ${dKm} km, about ${dMin} min.`);
    swapRoute(diff.kind==='rerouted'||switched?oldRoute:null,sim.route);
    setSim({route:sim.route,routeStops:riskStops(sim.routeCoords,sim.planHazard)});
  }else{
    sim.route=null;sim.routeCoords=null;
    if(diff.kind==='withheld'){addEvent('Route withheld: every path crosses the fire')}
    setStatus('withheld','Route withheld','Every path to the nearest safe assembly points crosses the fire. Hold position and wait for official instructions.');
    setSim({route:null});
  }
  sim.plan=next;
  sim.altsData=alts;sim.etaData=eta;
  setSim({alts:sim.showAlts?alts:[],blocked:blocked,eta:sim.showAlts?eta:[],assembly:assemblyFeatures()});
  renderLive();
}
function setStatus(kind,headline,detail){sim.status={kind,headline,detail}}

function maybeReplan(force){
  if(!sim.data||sim.planning)return;
  if(sim.vehicle&&sim.hazard&&pointInHazard(sim.vehicle,sim.hazard)){
    if(sim.status.kind!=='withheld'||!sim.caught){sim.caught=true;sim.route=null;sim.routeCoords=null;sim.plan={route:null,dest:null};setStatus('withheld','Inside the fire area','The vehicle is inside the burned area. No route can be offered. Shelter guidance and official instructions are needed.');addEvent('Vehicle inside the fire area');setSim({route:null});renderLive()}
    return;
  }
  const ahead=sim.routeCoords?sliceFrom(sim.routeCoords,sim.vehicleM):null;
  const now=performance.now();
  const why=force?'first':shouldReplan({now,lastAt:sim.lastPlanAt,minGapMs:Math.max(700,1800/sim.speed),retryGapMs:7500/sim.speed,neverPlanned:!sim.plan,route:sim.arrived?[]:ahead,hazard:sim.planHazard,area:sim.planArea,lastArea:sim.lastPlanArea||0,nearMeters:700});
  if(why==='near'&&now-sim.lastPlanAt<6000/sim.speed)return;
  if(why&&!sim.arrived){sim.lastPlanArea=sim.planArea;planRoute(why)}
}

// ---- run control ----
function selectRun(id){
  const run=runById(id),c=districtCentroid(run.geoid);
  cancelAnimationFrame(sim.raf);
  Object.assign(sim,{runId:run.id,playing:false,step:0,frameIndex:-1,vehicleM:0,vstep:null,route:null,routeCoords:null,plan:null,planning:false,
    planToken:sim.planToken+1,calls:0,reroutes:0,arrived:false,stale:false,events:[],vehicle:null,lastPlanAt:0,lastPlanArea:0,caught:false,uiAt:0,destName:run.primary});
  if(!c){setStatus('idle','Loading districts…','Recipient data is still loading.');renderLive();return}
  sim.origin=c;sim.data=buildRun(run,c);
  clearSim();
  setStatus('idle','Ready',`Press Play to start ${run.name}.`);
  showFrame(0);
  setSim({vehicle:{type:'Feature',properties:{},geometry:{type:'Point',coordinates:c}},arrow:arrowPolygon(c,0)});
  const dest=ASSEMBLY_POINTS.find(a=>a.name===run.primary);
  fitTo([c,sim.data.ignition,dest.lonlat],{});
  renderLive();
  planRoute('first');
}
function togglePlay(){
  if(!sim.data)return;
  if(sim.step>=RUN_STEPS){selectRun(sim.runId);return}
  sim.playing=!sim.playing;sim.lastTs=0;
  if(sim.playing){sim.raf=requestAnimationFrame(tick)}else cancelAnimationFrame(sim.raf);
  renderLive();
}
function tick(ts){
  if(!sim.playing)return;
  if(state.page!=='Overview'||state.mapMode!=='live'){sim.playing=false;return}
  const dt=sim.lastTs?Math.min(0.25,(ts-sim.lastTs)/1000):0;sim.lastTs=ts;
  const dSteps=dt*STEPS_PER_SEC*sim.speed;
  sim.step=Math.min(RUN_STEPS,sim.step+dSteps);
  // vehicle
  if(sim.routeCoords&&!sim.arrived&&sim.vstep){
    sim.vehicleM+=dSteps*sim.vstep;
    const at=pointAlong(sim.routeCoords,sim.vehicleM);
    sim.vehicle=at.point;
    setSim({vehicle:{type:'Feature',properties:{},geometry:{type:'Point',coordinates:at.point}},arrow:arrowPolygon(at.point,at.bearing)});
    if(sim.follow&&ts-sim.followAt>700){sim.followAt=ts;followVehicle(at.point,at.bearing)}
    if(at.done){sim.arrived=true;setStatus('arrived','Arrived',`Reached ${sim.destName} at ${clockText()}.`);addEvent(`Arrived at ${sim.destName}`);renderLive()}
  }
  const idx=Math.floor(sim.step);
  if(idx!==sim.frameIndex){showFrame(idx);maybeReplan(false)}
  if(ts-sim.uiAt>200){sim.uiAt=ts;paintClock()}
  if(sim.step>=RUN_STEPS){
    sim.playing=false;
    if(!sim.arrived)setStatus(sim.route?'clear':'withheld','Run complete',`${sim.reroutes} reroute${sim.reroutes===1?'':'s'} during the run.`);
    addEvent('Run complete');renderLive();return;
  }
  sim.raf=requestAnimationFrame(tick);
}
function paintClock(){
  const c=document.getElementById('run-clock');if(c)c.textContent=clockText();
  const b=document.getElementById('run-bar-fill');if(b)b.style.width=(sim.step/RUN_STEPS*100).toFixed(1)+'%';
  const w=document.getElementById('run-wind');const f=sim.data&&currentFrame();if(w&&f)w.textContent=`${compass(f.wind.dirFrom)} ${Math.round(f.wind.speed)} km/h`;
  const a=document.getElementById('run-area');if(a)a.textContent=sim.area.toFixed(1)+' km²';
}
function renderLive(){if(state.page!=='Overview'||state.mapMode!=='live')return;const list=document.querySelector('.run-list'),top=list?list.scrollTop:0;render();const again=document.querySelector('.run-list');if(again)again.scrollTop=top}
function enterLive(){
  if(!state.districts.length)return;
  if(!sim.data||sim.runId!==sim.data.run.id)selectRun(sim.runId);
  else{showFrame(Math.max(0,sim.frameIndex));renderLive()}
}
function leaveLive(){sim.playing=false;cancelAnimationFrame(sim.raf);sim.planToken++;sim.planning=false;clearSim()}

// ---- live screens ----
const STATUS_LABEL={idle:'Ready',clear:'Clear',rerouted:'Rerouted',withheld:'Withheld',arrived:'Arrived'};
const STATUS_ICON={idle:'clock',clear:'check',rerouted:'route',withheld:'shield',arrived:'check'};
function runPicker(){
  return `<section class="panel run-picker"><div class="panel-head"><h2>Fire runs</h2><span class="badge">${FIRE_RUNS.length} mock</span></div><div class="run-list" role="list">${FIRE_RUNS.map(r=>`<button class="run-card ${r.id===sim.runId?'selected':''}" role="listitem" data-run="${r.id}" aria-pressed="${r.id===sim.runId}"><span class="run-name">${esc(r.name)}</span><span class="run-meta">${esc(districtName(r.geoid))} · ${compass(r.windFrom)} wind ${r.windKmh} km/h${r.shift?' · wind shifts':''}</span><span class="run-blurb">${esc(r.blurb)}</span></button>`).join('')}</div><p class="run-note">Fictional exercise runs. Not forecasts.</p></section>`;
}
function statusCard(){
  const st=sim.status,r=sim.route&&sim.route.properties,f=sim.data&&currentFrame();
  const dest=sim.destName||'—';
  return `<section class="panel live-status"><div class="panel-head"><h2>Evacuation status</h2><span class="badge status-${st.kind}">${esc(STATUS_LABEL[st.kind]||'')}</span></div><div class="live-body"><div class="status-main status-${st.kind}" role="status" aria-live="polite">${icon(STATUS_ICON[st.kind]||'clock')}<div><strong>${esc(st.headline)}</strong><p>${esc(st.detail)}</p></div></div>${sim.stale?'<p class="stale">Routing is busy. Showing the last route.</p>':''}<dl class="live-facts"><div><dt>From</dt><dd>${esc(sim.data?districtName(sim.data.run.geoid):'—')}</dd></div><div><dt>To</dt><dd>${esc(dest)}</dd></div><div><dt>Route</dt><dd>${r?`${km(r.distance_m)} km · ${Math.max(1,Math.round(r.duration_s/60))} min`:'—'}</dd></div><div><dt>Fire</dt><dd><span id="run-area">${sim.area.toFixed(1)} km²</span> · <span id="run-wind">${f?`${compass(f.wind.dirFrom)} ${Math.round(f.wind.speed)} km/h`:'—'}</span></dd></div></dl><div class="live-toggles"><button class="toggle ${sim.showAlts?'on':''}" data-action="toggle-alts" aria-pressed="${sim.showAlts}">Alternatives</button><button class="toggle ${sim.follow?'on':''}" data-action="toggle-follow" aria-pressed="${sim.follow}">Follow vehicle</button></div>${sim.events.length?`<ol class="live-log">${sim.events.map(e=>`<li><time>${e.t}</time>${esc(e.text)}</li>`).join('')}</ol>`:''}<p class="live-foot">Live routing: ${state.connected?'PHAROS backend (OSRM)':'OSRM, direct'} · ${sim.calls} route check${sim.calls===1?'':'s'}. Mock fire run. Simplified decision support, not navigation.</p></div></section>`;
}
function overviewLive(){
  const run=runById(sim.runId);
  const transport=`<div class="timeline live-transport"><button class="play" data-action="live-play" aria-label="${sim.playing?'Pause':sim.step>=RUN_STEPS?'Restart':'Play'} fire run">${sim.playing?'Ⅱ':sim.step>=RUN_STEPS?'↺':'▶'}</button><label><span class="run-title">${esc(run.name)}</span><span id="run-clock" class="run-clock">${clockText()}</span></label><div class="run-bar" role="progressbar" aria-valuemin="0" aria-valuemax="${RUN_STEPS*STEP_MINUTES}" aria-valuenow="${Math.round(sim.step*STEP_MINUTES)}" aria-label="Run progress"><i id="run-bar-fill" style="width:${(sim.step/RUN_STEPS*100).toFixed(1)}%"></i></div><div class="speed" role="group" aria-label="Speed">${[1,2,4].map(v=>`<button class="speed-btn ${sim.speed===v?'on':''}" data-speed="${v}" aria-pressed="${sim.speed===v}">${v}×</button>`).join('')}</div><button class="link-btn" data-action="live-restart" aria-label="Restart run">${icon('refresh')}</button></div>`;
  return `<div class="stats"><div class="stat"><div class="stat-top">Fire run</div><div class="stat-value">${esc(run.name)}</div></div><div class="stat"><div class="stat-top">Burned area</div><div class="stat-value">${sim.area.toFixed(1)} km²</div></div><div class="stat"><div class="stat-top">Reroutes</div><div class="stat-value">${sim.reroutes}</div></div><div class="stat"><div class="stat-top">Route checks</div><div class="stat-value">${sim.calls}</div></div></div><div class="workspace"><section class="panel"><div class="panel-head"><div><h2>MOCK FIRE RUN / ${esc(run.name.toUpperCase())}</h2><p>FICTIONAL EXERCISE · LIVE OSRM ROUTING</p></div><span class="badge orange"><span class="dot" style="background:#d18a5e;margin:0"></span> LIVE</span></div>${map()}<div class="map-legend"><span><i class="legend-dot" style="background:#ff8a3c"></i>Fire</span><span><i class="legend-line" style="border-color:#38d9ff"></i>Route</span><span><i class="legend-line" style="border-color:#7e8d99"></i>Alternative</span><span><i class="legend-line" style="border-color:#ff5a4d;border-top-style:dashed"></i>Blocked</span><span><i class="legend-dot" style="background:#ff5a4d;opacity:.4"></i>Projected +15 min</span></div>${transport}</section><div class="right-stack">${statusCard()}</div></div><div class="bottom-grid">${runPicker()}<section class="panel"><div class="panel-head"><h2>Relay control</h2>${icon('leaf')}</div><div class="draft-body"><p>Compile observations and route constraints into a reviewable exercise message.</p>${btn(state.draft?'Review alert draft':'Prepare alert draft',state.draft?'open-alert':'draft','primary','arrow')}<p style="font-size:9px;text-align:center;margin:11px 0 0">${state.connected?'Connected backend':'Local template mode'} · No public alerts</p></div></section></div>`;
}

function render(){document.body.dataset.view=state.page;document.body.dataset.mapMode=state.mapMode;if(state.mapMode!=='live')$('#schematic-fallback').innerHTML=schematicMap();const titles={Console:['Communications console','Select municipalities and districts, then draft a multilingual exercise alert.'],Overview:['Live map','Real fire perimeters and the districts you are targeting.'],Incidents:['Incident queue','One exercise incident, from first signal to reviewed alert.'],Evidence:['Evidence stream','Every signal has a source. Every source has a timestamp.'],Alerts:['Alert workspace','Draft, review, and relay an exercise message.'],Activity:['Activity log','A traceable record of your review workflow, stored in this browser.'],Integrations:['Connected intelligence','Open tools and data, with credentials kept on the server.']};const [title,sub]=titles[state.page]||titles.Overview;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">◬</span><span>PHAROS</span></div><div class="brand-sub">WILDFIRE INTELLIGENCE</div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${[['Console','bell','Console'],['Overview','grid','Map'],['Evidence','layers','Evidence'],['Alerts','route','Drafts'],['Activity','clock','Activity']].map(([name,ic,label])=>`<button class="${state.page===name?'active':''}" data-nav="${name}" aria-label="${label}" title="${label}" ${state.page===name?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${name==='Console'&&state.selectedAreas.length?`<span class="count">${state.selectedAreas.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mission"><b>Built for a more resilient world.</b>Connecting early signals to informed action.</div><nav class="nav"><button class="${state.page==='Integrations'?'active':''}" data-nav="Integrations" aria-label="Integrations" title="Integrations">${icon('plug')}<span>Integrations</span></button></nav><div class="profile"><div class="avatar">OP</div><div><strong>Operator workspace</strong><small>Hackathon prototype</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><b class="status-brand">◬ PHAROS</b><span class="status-divider">/</span><strong>OPERATIONS</strong><span class="status-divider">/</span><span>${state.page.toUpperCase()}</span></div><div class="top-right"><span id="coordinates">34.2200° N 118.2300° W</span><span class="connection-label"><i class="dot"></i>${state.connected?'Backend connected':'Local workspace'}</span><span class="replay-pill">EXERCISE MODE</span><button data-nav="Activity" aria-label="View activity">${icon('bell')}</button></div></header><div class="page"><div class="page-head"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${btn('Export incident','export','','download')}${btn('Run scenario','scenario','primary','play')}</div></div>${state.page==='Console'?consoleView():state.page==='Overview'?overview():state.page==='Evidence'?`<div class="callout">All three observations below are synthetic replay fixtures. Source freshness is evaluated relative to the scenario clock, not the current time.</div><section class="panel">${evidenceRows()}</section>`:state.page==='Incidents'?`<section class="panel"><div class="panel-head"><h2>PHR–004 · Angeles ridge</h2><span class="badge orange">Unconfirmed</span></div><div class="full-panel"><p class="subtitle">Smoke signal near Zone 04. Camera, satellite and weather context available for review.</p><div class="actions" style="margin-top:20px">${btn('Open incident','overview','primary','arrow')}${btn('Choose scenario','scenario')}</div></div></section>`:state.page==='Alerts'?alerts():state.page==='Integrations'?integrations():`<section class="panel"><div class="panel-head"><h2>Review history</h2><span class="badge">Browser-local log</span></div>${state.logs.length?state.logs.map(l=>`<div class="activity-row"><time>${new Date(l.time).toLocaleTimeString()}</time><span>${esc(l.message)}</span></div>`).join(''):'<div class="empty">No actions yet. Open the incident and prepare your first alert draft.</div>'}</section>`}<footer class="footer"><span>PHAROS · Wildfire & Evacuation Relay</span><span>Simulation only. Follow official emergency guidance.</span></footer></div></main></div>`;bindInputs();updateMap(state)}
function bindInputs(){const t=$('#timeline');if(t)t.oninput=e=>setStage(Number(e.target.value));const a=$('#alert-text');if(a)a.oninput=e=>{state.draft.text=e.target.value;persist()};const cr=$('#console-reviewer');if(cr)cr.oninput=e=>{state.lastReviewer=e.target.value};const cc=$('#console-check');if(cc){cc.checked=!!state.consoleChecked;cc.onchange=e=>{state.consoleChecked=e.target.checked}};}
function setStage(stage){if(stage===state.stage)return;state.stage=stage;state.draft=null;state.mapMode='replay';log(`Scenario moved to stage ${stage+1}; previous draft and approval invalidated.`);render()}
async function api(path,options={}){const r=await fetch(`${state.api}${path}`,{...options,headers:{'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(60000)});if(!r.ok){let e;try{e=await r.json()}catch{}throw new Error(e?.detail||`Backend returned ${r.status}`)}return r.json()}
async function draft(){if(busy)return;busy=true;toast(state.connected?'Preparing draft with backend…':'Preparing scenario draft…');const requestedStage=state.stage;try{if(state.connected){const d=await api('/api/drafts',{method:'POST',body:JSON.stringify({stage:state.stage})});if(state.stage!==requestedStage){toast('Scenario changed while drafting. Please prepare a new draft.');return}state.draft={...d,server_id:d.id}}else state.draft=createDraft(state.stage);log(`Draft prepared using ${state.draft.engine}. ${state.draft.route_id?'Candidate '+state.draft.route_id+' passes scenario checks.':'No passing route; route instructions withheld.'}`);nav('Alerts')}catch(e){toast(e.message)}finally{busy=false}}
async function action(a){switch(a){case 'ai-plan':await aiPlan();break;case 'ai-translate':await aiTranslate();break;case 'send-sms':await aiSendSms();break;case 'replay-mode':leaveLive();state.mapMode='replay';render();focusReplay();break;case 'live-play':togglePlay();break;case 'live-restart':selectRun(sim.runId);break;case 'toggle-alts':sim.showAlts=!sim.showAlts;setSim({alts:sim.showAlts?(sim.altsData||[]):[],eta:sim.showAlts?(sim.etaData||[]):[]});renderLive();break;case 'toggle-follow':sim.follow=!sim.follow;renderLive();break;case 'live-mode':state.mapMode='live';render();enterLive();break;case 'close':$('#dialog').close();break;case 'select-all-areas':state.selectedAreas=state.districts.map(f=>f.properties.GEOID);persist();render();break;case 'clear-areas':state.selectedAreas=[];persist();render();break;case 'add-language':{const shown=new Set(recommendedLanguages(selectedFeatures()));modal('Add a language',`<p>Recommended languages come from the selected districts' demographics. You can add any supported language; non-English templates need native-speaker review before real use.</p><div class="lang-grid">${SUPPORTED_LANGUAGES.map(l=>`<button class="lang-pill ${shown.has(l.code)?'on':''}" data-lang="${l.code}">${esc(l.native)} · ${esc(l.label)}</button>`).join('')}</div>`);break}case 'broadcast':{if(busy)break;const plan=buildLanguagePlan(selectedFeatures(),state.languageMode);if(!plan.areas.length){toast('Select at least one municipality or district.');break}const reviewer=$('#console-reviewer').value.trim();if(!reviewer||!$('#console-check').checked){toast('Enter your name and review the complete exercise bundle.');break}busy=true;state.lastReviewer=reviewer;try{let result={status:'Recorded locally (exercise)',plan};if(state.connected)result=await api('/api/broadcast',{method:'POST',body:JSON.stringify({geoids:plan.areas.map(a=>a.geoid),mode:state.languageMode,reviewer,reviewed:true})});const accepted=result.plan||plan;state.threads.unshift({id:result.id,time:new Date().toISOString(),areas:accepted.areas.map(a=>a.name),languages:accepted.languages,message_count:accepted.message_count,reviewer,status:result.status,plan:accepted});state.threads=state.threads.slice(0,20);log(`Recorded exercise bundle: ${accepted.message_count} messages for ${accepted.areas.length} areas. ${result.status}.`);persist();render();toast('Complete multilingual bundle recorded.')}catch(e){toast('Bundle not recorded: '+e.message)}finally{busy=false}break}case 'overview':nav('Overview');break;case 'open-alert':nav('Alerts');break;case 'draft':await draft();break;case 'zoom-in':zoomMap(.5);break;case 'zoom-out':zoomMap(-.5);break;case 'reset':clearInterval(timer);state.playing=false;state.stage=0;state.draft=null;log('Replay reset; draft and approval cleared.');render();break;case 'play':if(state.playing){clearInterval(timer);state.playing=false;render()}else{if(state.stage===2)setStage(0);state.playing=true;render();timer=setInterval(()=>{if(state.stage<2)setStage(state.stage+1);if(state.stage===2){clearInterval(timer);state.playing=false;render()}},10000)}break;case 'scenario':modal('Choose an incident scenario',`<p>Replay a controlled incident. Every observation, road and destination is a fixture.</p><label class="form-row">Scenario<select id="scenario-choice"><option value="0">Initial signal · one route passes</option><option value="1">Expanding hazard · review again</option><option value="2">Road closure · no route passes</option></select></label><div class="actions">${btn('Load scenario','load-scenario','primary','play')}</div>`);break;case 'load-scenario':clearInterval(timer);state.playing=false;state.draft=null;state.stage=Number($('#scenario-choice').value);state.mapMode='replay';log(`Loaded scenario stage ${state.stage+1}.`);$('#dialog').close();nav('Overview');focusReplay();break;case 'approve':{const reviewer=$('#reviewer').value.trim();if(!reviewer||!$('#review-check').checked){toast('Enter your name and confirm the review checklist.');break}if(!state.draft.text.startsWith('EXERCISE ONLY')){toast('Keep the EXERCISE ONLY prefix in the message.');break}try{if(state.draft.server_id)await api(`/api/drafts/${state.draft.server_id}/approve`,{method:'POST',body:JSON.stringify({reviewer,text:state.draft.text,stage:state.stage,reviewed:true})});Object.assign(state.draft,{approved:true,reviewer,approved_at:new Date().toISOString()});log(`Exercise draft approved by ${reviewer}.`);render();toast('Draft approved for a test notification.')}catch(e){toast(e.message)}break}case 'revise':state.draft=createDraft(state.stage);log('Draft reopened; prior approval cleared.');render();break;case 'check-delivery':{const d=state.draft;if(!d?.server_id||busy)break;busy=true;try{const result=await api(`/api/drafts/${d.server_id}/delivery`);d.delivery=result.delivery;d.delivery_status=result.status;log(result.status);render();toast(result.status)}catch(e){toast(e.message)}finally{busy=false}break}case 'send':{const d=state.draft;if(!d?.approved||d.stage!==state.stage||d.delivered||busy)break;busy=true;try{let result={status:'Recorded in local test inbox'};if(d.server_id&&state.connected)result=await api(`/api/drafts/${d.server_id}/send`,{method:'POST',body:JSON.stringify({stage:state.stage})});d.delivered=true;d.delivery_status=result.status;d.delivery=result.delivery;log(`Test notification: ${result.status}. No public emergency alert was issued.`);render();toast(result.status)}catch(e){toast(e.message)}finally{busy=false}break}case 'export':{const blob=new Blob([JSON.stringify({project:'PHAROS',mode:'synthetic exercise',stage:state.stage,sources:SOURCES,hazards:hazards(state.stage),routes:checkRoutes(state.stage),draft:state.draft,activity:state.logs},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pharos-incident-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Incident report exported.');break}case 'connect':modal('Connect your Python backend',`<p>Run the included backend, then open its local dashboard for the simplest setup. For this hosted dashboard, use an HTTPS backend with this origin permitted by CORS. No credentials belong here.</p><label class="form-row">Backend URL<input id="api-url" placeholder="https://your-backend.example" value="${esc(state.api)}"></label><p>Connection enables server-side drafting and configured test delivery. Replay observations stay labeled as fixtures.</p><div class="actions">${btn('Use local mode','disconnect')}${btn('Test connection','test-connect','primary','plug')}</div>`);break;case 'disconnect':state.api='';state.connected=false;persist();$('#dialog').close();render();break;case 'test-connect':{const url=$('#api-url').value.trim().replace(/\/$/,'');try{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))throw Error('Use an HTTP or HTTPS URL.');state.api=url;const health=await api('/api/health');state.delivery=health.delivery;state.connected=true;persist();$('#dialog').close();render();toast('Backend connected.')}catch(e){state.connected=false;toast(`Connection failed: ${e.message}`)}break}}
}
document.addEventListener('click',e=>{const rc=e.target.closest('[data-run]');if(rc){selectRun(rc.dataset.run);return}const sp=e.target.closest('[data-speed]');if(sp){sim.speed=Number(sp.dataset.speed);renderLive();return}const fo=e.target.closest('[data-focus]');if(fo){state.focusArea=fo.dataset.focus;persist();render();return}const strategy=e.target.closest('[data-language-mode]');if(strategy){state.languageMode=strategy.dataset.languageMode;persist();render();return}const replayStep=e.target.closest('[data-replay-stage]');if(replayStep){clearInterval(timer);state.playing=false;setStage(Number(replayStep.dataset.replayStage));return}const ar=e.target.closest('[data-area]');if(ar){const id=ar.dataset.area;const i=state.selectedAreas.indexOf(id);if(i>=0)state.selectedAreas.splice(i,1);else state.selectedAreas.push(id);persist();render();return}const lg=e.target.closest('[data-lang]');if(lg){state.activeLang=lg.dataset.lang;persist();if($('#dialog').open)$('#dialog').close();render();return}const n=e.target.closest('[data-nav]');if(n){const tgt=n.dataset.nav;nav(tgt);if(tgt==='Overview'&&state.mapMode==='live')enterLive();return}const r=e.target.closest('[data-route]');if(r){state.selectedRoute=r.dataset.route;const route=checkRoutes(state.stage).find(x=>x.id===r.dataset.route);if(state.page==='Overview')render();modal(route.name,`<span class="badge ${route.blocked?'orange':''}">${route.blocked?'Excluded by scenario geometry':'Passes supplied geometry check'}</span><p>${route.distance} · ${route.duration} · synthetic route fixture</p><p>Destination: ${route.destination}. Road conditions and destination availability are unverified. Geometry checks cannot establish evacuation safety.</p>`);return}const evidence=e.target.closest('[data-evidence]');if(evidence){const s=SOURCES.find(x=>x.id===evidence.dataset.evidence);modal(s.name,`<span class="badge orange">SYNTHETIC REPLAY SOURCE</span><p>${esc(s.detail)}</p><div class="info-grid"><div><span>Source ID</span><strong>${s.id}</strong></div><div><span>Scenario observation time</span><strong>${s.time} PDT</strong></div></div>`);return}const l=e.target.closest('[data-layer]');if(l){state.layer=l.dataset.layer;render();return}const a=e.target.closest('[data-action]');if(a)action(a.dataset.action)});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-evidence]')){e.preventDefault();e.target.click()}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});
$('#schematic-fallback').innerHTML=schematicMap();
render();
fetch('data/districts.json').then(r=>r.json()).then(d=>{state.districts=d.features||[];state.districtMeta=d.metadata||{};updateMap(state);render();if(state.page==='Overview'&&state.mapMode==='live')enterLive()}).catch(()=>{});
initializeMap(id=>{const el=document.querySelector('[data-route="'+id+'"]');if(el)el.click()},geoid=>{const i=state.selectedAreas.indexOf(geoid);if(i>=0)state.selectedAreas.splice(i,1);else state.selectedAreas.push(geoid);persist();render()});
function loadPerimeters(){fetch((state.api||'')+'/api/live/perimeters?limit=25').then(r=>r.ok?r.json():null).then(d=>{if(d&&Array.isArray(d.perimeters)&&d.perimeters.length){state.perimeters={type:'FeatureCollection',features:d.perimeters};updateMap(state)}}).catch(()=>{})}
loadPerimeters();
{state.api=state.api||location.origin;api('/api/health').then(health=>{if(health.status!=='ok')return;state.delivery=health.delivery;state.connected=true;loadPerimeters();render()}).catch(()=>{state.connected=false})}

